import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val A = reader.readLine()?.trim()?.toLong() ?: return

    if (A == 1L) {
        println(1)
        return
    }

    val primeFactors = mutableListOf<Long>()
    var n = A
    var d = 2L
    while (d * d <= n) {
        while (n % d == 0) {
            primeFactors.add(d)
            n /= d
        }
        if (d == 2L) d = 3L else d += 2
    }
    if (n > 1) primeFactors.add(n)

    val uniqFactors = primeFactors.distinct().toTypedArray()
    val divisors = mutableListOf<Long>()

    fun generateDivisors(idx: Int, current: Long) {
        if (idx == uniqFactors.size) {
            divisors.add(current)
            return
        }
        val p = uniqFactors[idx]
        var val_ = 1L
        while (true) {
            generateDivisors(idx + 1, current * val_)
            if (val_ > Long.MAX_VALUE / p) break
            val_ *= p
            if (current * val_ > A) break
        }
    }

    generateDivisors(0, 1L)
    divisors.sort()

    val valid = mutableSetOf<Long>()
    for (div in divisors) {
        if (div == 1L) continue
        val candidate = div - 1
        if (candidate < 2) continue
        var temp = candidate
        var pFactor: Long = -1
        var d2 = 2L
        while (d2 * d2 <= temp) {
            if (temp % d2 == 0L) {
                pFactor = d2
                break
            }
            if (d2 == 2L) d2 = 3L else d2 += 2
        }
        if (pFactor == -1L) {
            pFactor = temp
        }
        var power = 1L
        while (power < candidate) {
            if (power > Long.MAX_VALUE / pFactor) {
                power = candidate + 1
                break
            }
            power *= pFactor
        }
        if (power == candidate) {
            valid.add(candidate)
        }
    }

    val validList = valid.toList()
    var count = 0L

    fun dfs(idx: Int, currentProd: Long, usedMask: Long) {
        if (currentProd == A) {
            count++
            return
        }
        if (idx == validList.size) return
        if (currentProd > A) return
        if (A % currentProd != 0L) return

        dfs(idx + 1, currentProd, usedMask)

        val q = validList[idx]
        val term = (q * q - 1) / (q - 1)
        if (term <= A && A % (currentProd * term) == 0L) {
            var pPower = q
            var termVal = term
            while (currentProd * termVal <= A && A % (currentProd * termVal) == 0L) {
                dfs(idx + 1, currentProd * termVal, usedMask)
                if (pPower > Long.MAX_VALUE / q) break
                pPower *= q
                termVal = (pPower * q - 1) / (q - 1)
            }
        }
    }

    dfs(0, 1L, 0L)
    println(count)
}
